#nullable enable // autogenerated

using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.UI;

namespace MVZ2Logic.UI
{
    [DisallowMultipleComponent]
    [RequireComponent(typeof(Image))]
    public class ImageResolver : MonoBehaviour, ISpriteResolver
    {
        private void OnEnable()
        {
            UpdateResolver();
        }
        public void UpdateResolver()
        {
            if (!spriteChanged)
            {
                spriteChanged = true;
                BaseSprite = Image.sprite;
            }
            SetSprite(BaseSprite);
        }
        public virtual void SetSprite(Sprite? sprite)
        {
            var final = sprite;
            if (Global.Resources != null && final != null)
            {
                final = Global.Resources.GetFinalSprite(final);
            }
            spriteChanged = true;
            BaseSprite = sprite;
            Image.sprite = final;
        }
        public virtual void SetEnabled(bool enabled)
        {
            Image.enabled = enabled;
        }
        public virtual void SetSpriteAndEnabled(Sprite? sprite)
        {
            SetSprite(sprite);
            Image.enabled = sprite;
        }
        public virtual Sprite? GetSprite()
        {
            return Image.sprite;
        }
        public Sprite? BaseSprite { get; private set; }
        public Image Image
        {
            get
            {
                if (!_image.Exists())
                {
                    _image = GetComponent<Image>();
                }
                return _image;
            }
        }
        public virtual RectTransform rectTransform { get => Image.rectTransform; }
        public virtual Color color { get => Image.color; set => Image.color = value; }
        public virtual bool raycastTarget { get => Image.raycastTarget; set => Image.raycastTarget = value; }
        public virtual Image.Type type { get => Image.type; set => Image.type = value; }
        public virtual Image.FillMethod fillMethod { get => Image.fillMethod; set => Image.fillMethod = value; }
        public virtual int fillOrigin { get => Image.fillOrigin; set => Image.fillOrigin = value; }
        public virtual float fillAmount { get => Image.fillAmount; set => Image.fillAmount = value; }
        private Image? _image;
        private bool spriteChanged;
    }
}
